      glow: 'border border-emerald-500/50 bg-background/90 text-emerald-400 shadow-[0_0_20px_rgba(16,185,129,0.3)] rounded-xl font-mono',
    };
    this.badgeClass = variantClasses[this.variant] || variantClasses.frosted;

    this.badge = null;
    this.targetX = -9999;
    this.targetY = -9999;
    this.currentX = -9999;
    this.currentY = -9999;
    this.rafId = null;
    this.lastTime = 0;

