import React, { useRef, useState } from 'react';
import { View, Text, StyleSheet, Animated, PanResponder, type ViewStyle, type LayoutChangeEvent } from 'react-native';

export interface CursorTooltipProps {
  content?: string;
  springDamping?: number;
  direction?: string;
  offsetX?: number;
  offsetY?: number;
  variant?: 'frosted' | 'accent' | 'dark' | 'minimal' | 'glow';
  collisionPadding?: number;
  style?: ViewStyle;
  children?: React.ReactNode;
}

const calculateTargetPosition = (
  x: number,
  y: number,
  offsetX: number,
  offsetY: number,
  direction: string,
  width = 0,
  height = 0
) => {
  switch (direction) {
    case 'top':
      return { x: x - width / 2, y: y - offsetY - height };
    case 'bottom':
      return { x: x - width / 2, y: y + offsetY };
    case 'left':
      return { x: x - offsetX - width, y: y - height / 2 };
    case 'right':
      return { x: x + offsetX, y: y - height / 2 };
    case 'top-left':
      return { x: x - offsetX - width, y: y - offsetY - height };
    case 'top-right':
      return { x: x + offsetX, y: y - offsetY - height };
    case 'bottom-left':
      return { x: x - offsetX - width, y: y + offsetY };
    case 'bottom-right':
    default:
      return { x: x + offsetX, y: y + offsetY };
  }
};

export const CursorTooltip: React.FC<CursorTooltipProps> = ({
  content = 'Explore Showcase',
  springDamping = 20,
  direction = 'bottom-right',
  offsetX = 16,
  offsetY = 16,
  variant = 'frosted',
  collisionPadding = 12,
  style,
  children,
}) => {
  const pan = useRef(new Animated.ValueXY({ x: 0, y: 0 })).current;
  const [active, setActive] = useState(false);
  const badgeSizeRef = useRef({ width: 0, height: 0 });

  const panResponder = useRef(
    PanResponder.create({
      onStartShouldSetPanResponder: () => false,
      onMoveShouldSetPanResponder: () => true,
      onPanResponderGrant: (evt) => {
        setActive(true);
        const pos = calculateTargetPosition(
          evt.nativeEvent.locationX,
          evt.nativeEvent.locationY,
          offsetX,
          offsetY,
          direction,
          badgeSizeRef.current.width,
          badgeSizeRef.current.height
        );
        pan.setValue(pos);
      },
      onPanResponderMove: (evt) => {
        const pos = calculateTargetPosition(
          evt.nativeEvent.locationX,
          evt.nativeEvent.locationY,
          offsetX,
          offsetY,
          direction,
          badgeSizeRef.current.width,
          badgeSizeRef.current.height
        );
        Animated.spring(pan, {
          toValue: pos,
          bounciness: 0,
          speed: springDamping,
          useNativeDriver: false,
        }).start();
      },
      onPanResponderRelease: () => {
        setActive(false);
      },
      onPanResponderTerminate: () => {
        setActive(false);
      },
    })
  ).current;

  const onBadgeLayout = (e: LayoutChangeEvent) => {
    badgeSizeRef.current = {
      width: e.nativeEvent.layout.width,
      height: e.nativeEvent.layout.height,
    };
  };

  const getBadgeStyle = () => {
    switch (variant) {
      case 'accent':
        return styles.accentBadge;
      case 'dark':
        return styles.darkBadge;
      case 'minimal':
        return styles.minimalBadge;
      case 'glow':
        return styles.glowBadge;
      case 'frosted':
      default:
        return styles.frostedBadge;
    }
  };

  const getTextStyle = () => {
    switch (variant) {
      case 'accent':
        return styles.accentText;
      case 'dark':
        return styles.darkText;
      case 'minimal':
        return styles.minimalText;
      case 'glow':
        return styles.glowText;
      case 'frosted':
      default:
        return styles.frostedText;
    }
  };

  return (
    <View style={[styles.container, style]} {...panResponder.panHandlers}>
      {children}
      {active && (
        <Animated.View
          onLayout={onBadgeLayout}
          pointerEvents="none"
          style={[
            styles.badge,
            getBadgeStyle(),
            {
              transform: [{ translateX: pan.x }, { translateY: pan.y }],
            },
          ]}
        >
          <Text style={getTextStyle()}>{content}</Text>
        </Animated.View>
      )}
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    position: 'relative',
  },
  badge: {
    position: 'absolute',
    top: 0,
    left: 0,
    paddingHorizontal: 12,
    paddingVertical: 6,
    borderRadius: 12,
    shadowColor: '#000',
